class Codec:
    def serialize(self, root: TreeNode | None) -> str:
        parts = []

        def write(node: TreeNode | None) -> None:
            if node is None:
                parts.append("|")
                return

            parts.append(str(node.val))
            write(node.left)
            write(node.right)

